files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #2b2b3c;
  color: #e0e0e0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #3a3a4e;
  border: 4px solid #5a5a72;
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 8px 8px 0 #1e1e2a;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  text-align: center;
  color: #f0c040;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 3px 3px 0 #1e1e2a;
}

.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.tab {
  font: inherit;
  font-size: 1rem;
  padding: 10px 20px;
  background: #4a4a62;
  color: #b0b0c0;
  border: 3px solid #5a5a72;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  flex: 1 1 auto;
  min-width: 80px;
}

.tab:hover {
  background: #5a5a72;
  color: #ffffff;
}

.tab:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
}

.tab:active {
  background: #6a6a82;
  transform: translate(2px, 2px);
}

.tab.active {
  background: #f0c040;
  color: #1e1e2a;
  border-color: #f0c040;
  font-weight: 700;
}

.tab.active:hover {
  background: #f0c040;
  color: #1e1e2a;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

textarea {
  font: inherit;
  font-size: 1rem;
  padding: 12px;
  background: #2b2b3c;
  color: #e0e0e0;
  border: 3px solid #5a5a72;
  resize: vertical;
  min-height: 140px;
  width: 100%;
}

textarea:focus {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
  border-color: #f0c040;
}

textarea::placeholder {
  color: #7a7a8a;
}

.char-count {
  font-size: 0.9rem;
  color: #a0a0b0;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .tab {
    padding: 8px 12px;
    font-size: 0.95rem;
    min-width: 60px;
  }
  textarea {
    min-height: 120px;
  }
}

(function () {
  'use strict';

  const tabs = Array.from(document.querySelectorAll('[role="tab"]'));
  const panels = tabs.map(tab => document.getElementById(tab.getAttribute('aria-controls')));
  const textareas = panels.map(panel => panel.querySelector('textarea'));
  const counts = panels.map(panel => panel.querySelector('.char-count'));

  // Restore saved content from localStorage
  const storageKey = 'pixel-notes';
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(storageKey)) || {};
  } catch (e) {
    saved = {};
  }

  textareas.forEach((ta, i) => {
    const key = tabs[i].id.replace('tab-', '');
    if (saved[key]) {
      ta.value = saved[key];
    }
    updateCount(i);
  });

  function updateCount(index) {
    const len = textareas[index].value.length;
    counts[index].textContent = len + (len === 1 ? ' character' : ' characters');
  }

  function saveState() {
    const data = {};
    tabs.forEach((tab, i) => {
      data[tab.id.replace('tab-', '')] = textareas[i].value;
    });
    try {
      localStorage.setItem(storageKey, JSON.stringify(data));
    } catch (e) {
      // ignore storage errors
    }
  }

  function activateTab(index) {
    tabs.forEach((tab, i) => {
      const isActive = i === index;
      tab.classList.toggle('active', isActive);
      tab.setAttribute('aria-selected', isActive ? 'true' : 'false');
      tab.tabIndex = isActive ? 0 : -1;
      panels[i].hidden = !isActive;
    });
    tabs[index].focus();
  }

  tabs.forEach((tab, i) => {
    tab.addEventListener('click', () => {
      activateTab(i);
    });

    tab.addEventListener('keydown', (e) => {
      let target = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        target = (i + 1) % tabs.length;
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        target = (i - 1 + tabs.length) % tabs.length;
      } else if (e.key === 'Home') {
        target = 0;
      } else if (e.key === 'End') {
        target = tabs.length - 1;
      }
      if (target !== null) {
        e.preventDefault();
        activateTab(target);
      }
    });
  });

  textareas.forEach((ta, i) => {
    ta.addEventListener('input', () => {
      updateCount(i);
      saveState();
    });
  });
})();
